function initMobileMenu(){const e=document.getElementById("mobileMenuBtn"),n=document.getElementById("mainNav");e&&n&&e.addEventListener("click",()=>{e.classList.toggle("active"),n.classList.toggle("active")})}async function loadTripsFromAPI(){const e=document.getElementById("trips-grid");if(e){e.innerHTML='<div style="grid-column: 1 / -1; text-align: center; color: var(--color-text-secondary);">Buscando destinos incríveis...</div>';try{const n=await fetch(`/.netlify/functions/trips?t=${Date.now()}`);if(!n.ok)throw 404===n.status?new Error("A rota de viagens não foi encontrada."):500===n.status?new Error("Erro interno no servidor do Netlify."):new Error(`Erro na comunicação. Status: ${n.status}`);const t=await n.json();if(!Array.isArray(t)||0===t.length)return void(e.innerHTML='<div style="grid-column: 1 / -1; text-align: center;">Nenhum roteiro programado no momento.</div>');e.innerHTML="",t.forEach(n=>{const t=createTripCard(n);e.appendChild(t)})}catch(n){console.error("Falha ao carregar viagens:",n),e.innerHTML='<div style="grid-column: 1 / -1; text-align: center; color: #EF4444;">Não foi possível carregar as viagens. Tente recarregar a página.</div>'}}}function createTripCard(e){const n=document.createElement("article");n.className="trip-card";const t="available"===e.status,r=t?"":"esgotado",i=t?"Disponível":"Esgotado";return n.innerHTML=`\n    <div class="trip-image-wrapper">\n      <span class="trip-badge ${r}">${i}</span>\n      <img src="${e.image}" alt="Viagem para ${e.title}" loading="lazy" />\n    </div>\n    <div class="trip-content">\n      <h3 class="trip-title">${e.title}</h3>\n      <p class="trip-date">\n        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">\n          <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>\n          <line x1="16" y1="2" x2="16" y2="6"></line>\n          <line x1="8" y1="2" x2="8" y2="6"></line>\n          <line x1="3" y1="10" x2="21" y2="10"></line>\n        </svg>\n        ${e.date}\n      </p>\n      <p class="trip-description">${e.description||""}</p>\n      <a href="${e.link||"#"}" class="btn btn-primary">Ver Detalhes</a>\n    </div>\n  `,n}document.addEventListener("DOMContentLoaded",()=>{initMobileMenu(),loadTripsFromAPI()});